#pragma once
int runSwing402(){juce::ScopedJuceInitialiser_GUI gui;auto require=[](bool ok,const char* what){if(!ok)throw std::runtime_error(what);};try{LibraryStore::writeSwing("D",{false,50});LibraryStore::writeSwing("C",{false,50});Processor p(false),linked(false);p.autoSave=linked.autoSave=false;p.setSwingLink(true,"D");linked.setSwingLink(true,"D");p.setSwing(true,75);linked.syncLinkedSwing();require(linked.swingEnabled&&linked.swingAmount==75,"sequencer and slice share swing group values");p.sequenceSwingGrid=.25;p.sequence.bars=1;p.sequence.notes={{1,60,100,1,0,.1},{2,62,100,1,.25,.125},{3,64,100,1,.5,.1}};p.sequenceEnabled=true;p.prepareToPlay(48000,128);juce::MidiBuffer midi;p.renderSequenceMidi(midi,0,1./24000,12000,true);bool on=false,off=false;for(auto e:midi){auto m=e.getMessage();if(m.getNoteNumber()==62&&m.isNoteOn())on=e.samplePosition==9000;if(m.getNoteNumber()==62&&m.isNoteOff())off=e.samplePosition==10500;}require(on&&off,"swung onset and noteoff keep consistent order");auto exported=p.sequenceForExport();require(std::abs(exported.notes[1].beat-.375)<1e-8&&std::abs(exported.notes[1].length-.0625)<1e-8&&p.sequence.notes[1].beat==.25,"non destructive swing and MIDI export");p.setSwing(false,75);require(p.sequenceSwingBeat(.25)==.25,"swing bypass");p.setSwing(true,50);require(std::abs(p.sequenceSwingBeat(.37)-.37)<1e-8,"zero swing straight");
 auto data=std::make_shared<AudioData>();data->rate=48000;data->path=LibraryStore::root().getChildFile("Loop.wav").getFullPathName();data->buffer.setSize(1,96000);data->buffer.clear();p.audio=data;p.sourceBpm=120;p.split(16,false);p.sequenceEnabled=false;p.setSwing(true,50);SequenceClip straight;require(straight.fromMidi(p.makeMidi(120)),"straight slice MIDI");p.setSwing(true,75);p.sequenceFromSlices();require(p.sequence.notes.size()==straight.notes.size(),"slice sequence import");for(size_t i=0;i<straight.notes.size();++i)require(std::abs(p.sequence.notes[i].beat-straight.notes[i].beat)<1e-6,"slice-derived sequence is not double swung");
 SequencerEditor panel(p);panel.setSize(900,450);require(panel.swing402UiForCheck(),"sequencer swing controls/groups");auto png=LibraryStore::root().getChildFile("swing402.png").createOutputStream();juce::PNGImageFormat fmt;if(png)fmt.writeImageToStream(panel.createComponentSnapshot(panel.getLocalBounds()),*png);
 RackProcessor rack;RackEditor editor(rack);require(editor.master402UiForCheck(),"master key root and MIN/MAJ independent");auto out=LibraryStore::root().getChildFile("master402.png").createOutputStream();if(out)fmt.writeImageToStream(editor.createComponentSnapshot(editor.getLocalBounds()),*out);std::cout<<"Shared swing groups, note timing, note-offs, MIDI export, no double swing, master key root/quality UI passed.\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 4021;}}
